// ========== 1. 旧写法：手动字段 + 访问器 ==========
public class LegacyUser
{
    private string _name;            // 手写 backing field
    public string Name
    {
        get { return _name; }
        set { _name = value; }
    }
}

// ========== 2. 新写法：自动属性 + 初始化器 ==========
public class User
{
    public string Name { get; set; } = "匿名";   // 带默认值
    public int Age { get; private set; }         // 外部只读、内部可改
    public DateTime CreatedAt { get; } = DateTime.Now; // 只有 get，构造后不可变

    public User(string name, int age)
    {
        Name = name;
        Age = age;                  // private set 允许在类内部赋值
    }
}

// ========== 3. 混合写法：set 加校验，get 保持自动 ==========
public class Score
{
    private int _value;
    public int Value
    {
        get => _value;             // 自动 get 的逻辑由编译器生成
        set => _value = value switch
        {
            >= 0 and <= 100 => value,
            _ => throw new ArgumentOutOfRangeException(nameof(value), "分数必须在 0~100")
        };
    }
}

// ========== 4. 完整演示 ==========
var u = new User("张三", 20);
u.Name = "李四";          // 外部可改 Name
// u.Age = 21;           // ✘ 编译错误：Age 的 set 是 private
Console.WriteLine($"{u.Name} / {u.Age} / {u.CreatedAt:HH:mm}");

var s = new Score();
s.Value = 95;             // ✔
// s.Value = 150;        // ✘ 抛 ArgumentOutOfRangeException
Console.WriteLine(s.Value);

