// 自动属性 + 手动访问器混用：UI 数据绑定的经典场景
public class ViewModel : System.ComponentModel.INotifyPropertyChanged
{
    public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;

    private string _name = "";
    public string Name
    {
        get => _name;
        set
        {
            if (_name == value) return;        // 值未变不通知
            _name = value;
            PropertyChanged?.Invoke(this, new(nameof(Name)));
        }
    }

    // 自动属性 + 私有 set：外部只读、内部可改
    public DateTime LoadedAt { get; private set; } = DateTime.Now;

    // 自动属性 + 只读：构造函数赋值
    public string Source { get; } = "cache";

    public void Refresh() => LoadedAt = DateTime.Now;
}

// 完整演示：订阅变更事件
var vm = new ViewModel();
vm.PropertyChanged += (_, e) => Console.WriteLine($"属性 {e.PropertyName} 变化");
vm.Name = "张三";      // 输出：属性 Name 变化
vm.Name = "张三";      // 相同值：不触发事件
vm.Refresh();          // 内部修改 LoadedAt（外部无法赋值）
Console.WriteLine($"{vm.Name} / {vm.LoadedAt:HH:mm:ss} / {vm.Source}");

