public static class Geometry
{
    public const double Pi = Math.PI;
    public static double Tau => 2 * Math.PI;

    // 面积 / 周长：一行表达式
    public static double CircleArea(double r) => Pi * r * r;
    public static double CirclePerimeter(double r) => Tau * r;
    public static double RectArea(double w, double h) => w * h;

    // 多个分支也可写成表达式主体（嵌套三元）
    public static string Classify(double r) =>
        r <= 0 ? "无效半径" : r < 1 ? "小圆" : r < 10 ? "中圆" : "大圆";

    // 表达式主体属性
    public static double GoldenRatio => (1 + Math.Sqrt(5)) / 2;
}

// 完整演示
Console.WriteLine(Geometry.CircleArea(1));       // 3.141592653589793
Console.WriteLine(Geometry.CirclePerimeter(1));  // 6.283185307179586
Console.WriteLine(Geometry.Classify(5));         // 中圆
Console.WriteLine(Geometry.GoldenRatio);         // 1.618033988749895

