#nullable enable
using System.Collections.Generic;

public class UserService
{
    private readonly Dictionary<int, string> _users = new()
    {
        [1] = "张三",
        [2] = "李四",
    };

    // 返回可空：用户可能不存在
    public string? GetName(int id)
    {
        // 字典里没有时 GetValueOrDefault 返回 null
        return _users.TryGetValue(id, out var name) ? name : null;
    }

    public int GetNameLength(int id)
    {
        string? name = GetName(id);
        // return name.Length;          // ✘ CS8602：可能为 null
        if (name != null)
            return name.Length;         // ✔ 流分析确认此分支已判空
        return 0;                        // ✔ 兜底
    }

    public string NameOrDefault(int id) =>
        GetName(id) ?? "未知用户";        // ?? 提供回退值
}

// 完整演示：编译器全程帮你盯住 null
var svc = new UserService();
Console.WriteLine(svc.GetNameLength(1));      // 2
Console.WriteLine(svc.GetNameLength(99));     // 0（不存在）
Console.WriteLine(svc.NameOrDefault(2));      // 李四
Console.WriteLine(svc.NameOrDefault(99));     // 未知用户

