public class Order
{
    public string Customer { get; set; } = "";
    public string? Note { get; set; }
    public Address? ShipTo { get; set; }
}
public class Address
{
    public string City { get; set; } = "";
    public string? Street { get; set; }
}

Order? order = null;

// ① 传统写法：层层判空（啰嗦）
if (order != null && order.ShipTo != null && order.ShipTo.City != null)
    Console.WriteLine(order.ShipTo.City);

// ② ?. 链式：一行搞定，任一环节为 null 整体为 null
string? city1 = order?.ShipTo?.City;
Console.WriteLine(city1 ?? "（无城市信息）");

// ③ switch 属性模式：结构化的判空分支
string label = order switch
{
    { ShipTo: { City: { Length: > 0 } c } } => $"收货城市：{c}",
    { ShipTo: null }                        => "未填写收货地址",
    _                                       => "信息缺失"
};
Console.WriteLine(label);

// ④ null 合并 + TryGetValue 安全取值
Dictionary<int, string> users = new() { [1] = "张三" };
string name = users.TryGetValue(2, out var n) ? n : "匿名";
Console.WriteLine(name);                    // 匿名

// 有值的情况
order = new Order { Customer = "李四", ShipTo = new Address { City = "北京" } };
Console.WriteLine(order?.ShipTo?.City ?? "无");   // 北京

