// ========== 基础：值相等 + 解构 ==========
public record Person(string Name, int Age);

var p1 = new Person("张三", 20);
var p2 = new Person("张三", 20);

Console.WriteLine(p1 == p2);                 // True  —— 值相等
Console.WriteLine(ReferenceEquals(p1, p2));  // False —— 仍是不同对象
Console.WriteLine(p1);                       // Person { Name = 张三, Age = 20 }
var (name, age) = p1;                        // 自动解构
Console.WriteLine($"{name} / {age}");

// ========== with：非破坏性复制修改 ==========
var p3 = p1 with { Age = 21 };               // p1 不受影响
Console.WriteLine(p1);                       // Person { Name = 张三, Age = 20 }
Console.WriteLine(p3);                       // Person { Name = 张三, Age = 21 }

