public static class DateExtensions
{
    // 是否为工作日（周一~周五）
    public static bool IsWeekday(this DateTime d)
        => d.DayOfWeek is >= DayOfWeek.Monday and <= DayOfWeek.Friday;

    // 下一个周一
    public static DateTime NextMonday(this DateTime d)
    {
        int days = ((int)DayOfWeek.Monday - (int)d.DayOfWeek + 7) % 7;
        return days == 0 ? d.AddDays(7) : d.AddDays(days);
    }

    // 周岁计算（处理闰日生日）
    public static int AgeOn(this DateTime birth, DateTime today)
    {
        int age = today.Year - birth.Year;
        return today < birth.AddYears(age) ? age - 1 : age;
    }
}

// 链式使用
var today = new DateTime(2024, 8, 29);
Console.WriteLine(today.IsWeekday());            // True
Console.WriteLine(today.NextMonday().ToString("yyyy-MM-dd"));  // 2024-09-02

var birth = new DateTime(2000, 2, 29);
Console.WriteLine(birth.AgeOn(today));           // 24（闰日生日的周岁算法）
Console.WriteLine(birth.AgeOn(today.AddYears(1))); // 25

