public interface IReporter
{
    void Report(string message);

    // 默认实现：组合出新的方法
    void ReportWarning(string message) => Report($"[警告] {message}");
    void ReportError(string message)   => Report($"[错误] {message}");

    // 默认属性实现
    string Prefix { get; set; } = "[报告]";
}

public class ConsoleReporter : IReporter
{
    public void Report(string message) => Console.WriteLine(message);
    // Prefix / ReportWarning / ReportError 全部继承默认实现
}

public class StyledReporter : IReporter
{
    public void Report(string message) => Console.WriteLine($"══ {message} ══");

    // 想改写默认实现时，用 base 调用接口版本再增强
    public void ReportError(string message)
    {
        Console.WriteLine("--- 错误开始 ---");
        base.ReportError(message);     // 调用 IReporter 的默认实现
        Console.WriteLine("--- 错误结束 ---");
    }
}

// 完整演示
IReporter a = new ConsoleReporter();
a.ReportWarning("CPU 过高");      // [警告] CPU 过高
a.ReportError("磁盘将满");        // [错误] 磁盘将满

IReporter b = new StyledReporter();
b.Report("启动");                 // ══ 启动 ══
b.ReportError("连接超时");        // 带边框的完整错误流程

