[Flags]
public enum Permissions
{
    None   = 0,
    Read   = 1 << 0,     // 1
    Write  = 1 << 1,     // 2
    Delete = 1 << 2,     // 4
    Admin  = Read | Write | Delete
}

public static class Auth
{
    // 全部包含才算通过
    public static bool Has(this Permissions user, Permissions required)
        => (user & required) == required;

    public static Permissions Grant(Permissions user, Permissions add)
        => user | add;

    public static Permissions Revoke(Permissions user, Permissions remove)
        => user & ~remove;
}

// 完整演示
var alice = Permissions.Read | Permissions.Write;
Console.WriteLine(alice);                       // Read, Write
Console.WriteLine(alice.Has(Permissions.Read));    // True
Console.WriteLine(alice.Has(Permissions.Admin));   // False（缺 Delete）

alice = Auth.Grant(alice, Permissions.Delete);
Console.WriteLine(alice.Has(Permissions.Admin));   // True

alice = Auth.Revoke(alice, Permissions.Write);
Console.WriteLine(alice);                          // Read, Delete

// 位运算判断 vs HasFlag
Console.WriteLine((alice & Permissions.Read) != 0);   // True
Console.WriteLine(alice.HasFlag(Permissions.Read));   // True

