public static IEnumerable<int> Positive(IEnumerable<int> src)
{
    if (src == null) throw new ArgumentNullException(nameof(src)); // 调用即校验
    return Iterator();

    IEnumerable<int> Iterator()
    {
        foreach (var n in src)
            if (n > 0) yield return n;
    }
}

