// 本地递归：原地快速排序（无需额外类型）
static void QuickSort<T>(T[] arr) where T : IComparable<T>
{
    void Sort(int lo, int hi)
    {
        if (lo >= hi) return;
        int i = lo, j = hi;
        var pivot = arr[(lo + hi) / 2];
        while (i <= j)
        {
            while (arr[i].CompareTo(pivot) < 0) i++;
            while (arr[j].CompareTo(pivot) > 0) j--;
            if (i <= j) (arr[i], arr[j]) = (arr[j], arr[i]);  // 交换
            i++; j--;
        }
        Sort(lo, j); Sort(i, hi);
    }
    Sort(0, arr.Length - 1);
}

var nums = new[] { 5, 2, 8, 1, 9, 3 };
QuickSort(nums);
Console.WriteLine(string.Join(",", nums));   // 1,2,3,5,8,9

