static Dictionary<char, int> CountChars(string s)
{
    var dict = new Dictionary<char, int>();
    void Add(char c) => dict[c] = dict.TryGetValue(c, out var n) ? n + 1 : 1;
    foreach (var c in s) Add(char.ToLower(c));
    return dict;
}
