// 动态构造表达式：p => p.Age >= value
static Expression<Func<T, bool>> GreaterThan<T>(string prop, object value)
{
    var p = Expression.Parameter(typeof(T), "x");
    var propAccess = Expression.Property(p, prop);
    var constant = Expression.Constant(value, value.GetType());
    var compare = Expression.GreaterThanOrEqual(propAccess, constant);
    return Expression.Lambda<Func<T, bool>>(compare, p);
}

