using System.Linq.Expressions;

public record Product(int Id, string Name, decimal Price, bool InStock);

// 动态拼接：p => p.Price >= min && p.Price <= max
static Expression<Func<T, bool>> InRange<T>(string prop, double min, double max)
{
    var p = Expression.Parameter(typeof(T), "x");
    var member = Expression.Property(p, prop);
    var lo = Expression.Constant(Convert.ChangeType(min, member.Type), member.Type);
    var hi = Expression.Constant(Convert.ChangeType(max, member.Type), member.Type);
    var body = Expression.AndAlso(
        Expression.GreaterThanOrEqual(member, lo),
        Expression.LessThanOrEqual(member, hi));
    return Expression.Lambda<Func<T, bool>>(body, p);
}

// 动态拼接：p => p.Name.Contains(keyword)
static Expression<Func<T, bool>> NameContains<T>(string keyword)
{
    var p = Expression.Parameter(typeof(T), "x");
    var name = Expression.Property(p, "Name");
    var contains = Expression.Call(name,
        typeof(string).GetMethod("Contains", new[] { typeof(string) })!,
        Expression.Constant(keyword));
    return Expression.Lambda<Func<T, bool>>(contains, p);
}

