using System.Net.Http;

// 指数退避重试：最多尝试 4 次，间隔 1s/2s/4s
static async Task<string> FetchWithRetryAsync(HttpClient http, string url, int maxRetries = 4)
{
    for (int attempt = 1; ; attempt++)
    {
        try
        {
            return await http.GetStringAsync(url);
        }
        catch (HttpRequestException) when (attempt < maxRetries)
        {
            int delayMs = (int)Math.Pow(2, attempt - 1) * 1000;   // 1s, 2s, 4s
            Console.WriteLine($"第 {attempt} 次失败，{delayMs / 1000}s 后重试");
            await Task.Delay(delayMs);
        }
    }
}

// 并发下载多个资源（WhenAll）：总耗时≈最慢的那个
static async Task DownloadAllAsync(HttpClient http, params string[] urls)
{
    var tasks = urls.Select(url => http.GetStringAsync(url)).ToArray();
    var results = await Task.WhenAll(tasks);      // 全部完成才继续
    foreach (var r in results) Console.WriteLine($"收到 {r.Length} 字符");
}

