// 分批执行：一次最多并发 3 个，批次间串行
static async Task RunInBatchesAsync(IEnumerable<string> urls, int batchSize)
{
    var list = urls.ToList();
    for (int i = 0; i < list.Count; i += batchSize)
    {
        var batch = list.Skip(i).Take(batchSize);
        var tasks = batch.Select(u => FetchAsync(u));
        await Task.WhenAll(tasks);      // 等本批全部完成再开下一批
        Console.WriteLine($"批次 {i / batchSize + 1} 完成");
    }
}

// 信号量限流：全局最多 N 个并发（更平滑，无批次边界）
static async Task RunThrottledAsync(IEnumerable<string> urls, int maxConcurrent)
{
    using var sem = new SemaphoreSlim(maxConcurrent);
    var tasks = urls.Select(async u =>
    {
        await sem.WaitAsync();
        try { return await FetchAsync(u); }
        finally { sem.Release(); }
    });
    var results = await Task.WhenAll(tasks);
    Console.WriteLine($"全部完成，共 {results.Length} 个结果");
}

// 首败即停：任何任务失败就取消其余
static async Task RunFailFastAsync(IEnumerable<string> urls, CancellationToken ct)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
    var tasks = urls.Select(u => FetchAsync(u, cts.Token)).ToArray();
    var first = await Task.WhenAny(tasks);        // 谁先完成/失败
    if (first.IsFaulted) cts.Cancel();            // 失败则取消所有
    await Task.WhenAll(tasks);                    // 等全部收尾
}

static async Task<string> FetchAsync(string url, CancellationToken ct = default)
{
    await Task.Delay(Random.Shared.Next(50, 300), ct);
    return url;
}

