// 读写锁：读多写少的缓存（读者可并行，写者独占）
public class SafeCache<TKey, TValue> where TKey : notnull
{
    private readonly Dictionary<TKey, TValue> _map = new();
    private readonly ReaderWriterLockSlim _lock = new();

    public TValue? Get(TKey key)
    {
        _lock.EnterReadLock();      // 多个读者可并行
        try { return _map.TryGetValue(key, out var v) ? v : default; }
        finally { _lock.ExitReadLock(); }
    }

    public void Set(TKey key, TValue value)
    {
        _lock.EnterWriteLock();     // 写者独占
        try { _map[key] = value; }
        finally { _lock.ExitWriteLock(); }
    }
}

