public enum OrderStatus { Pending, Paid, Shipped, Completed, Cancelled, Refunded }

// 状态机：根据当前状态 + 动作计算下一个状态
static OrderStatus Next(OrderStatus s, string action) => (s, action) switch
{
    (OrderStatus.Pending, "pay")      => OrderStatus.Paid,
    (OrderStatus.Paid, "ship")        => OrderStatus.Shipped,
    (OrderStatus.Shipped, "deliver")  => OrderStatus.Completed,
    (OrderStatus.Pending, "cancel")   => OrderStatus.Cancelled,
    (OrderStatus.Paid, "refund")      => OrderStatus.Refunded,
    (OrderStatus.Cancelled, "reopen") => OrderStatus.Pending,
    _ => throw new InvalidOperationException($"非法迁移：{s} -> {action}")
};

// 元组模式 + when 子句：运费计算
static decimal ShippingFee(decimal amount, bool vip, bool rush) => (vip, rush) switch
{
    (true, _)            => 0m,               // VIP 免邮
    (false, true)        => amount * 0.2m,    // 加急 20%
    (false, false) when amount >= 99 => 0m,   // 满 99 包邮
    _                    => 8m
};

