// 同时支持同步与异步释放的资源类
public sealed class TempFile : IDisposable, IAsyncDisposable
{
    private readonly string _path;
    private FileStream? _stream;
    private bool _disposed;

    public TempFile(string prefix)
    {
        _path = Path.GetTempFileName();
        _stream = File.Create(_path);
        Console.WriteLine($"已创建临时文件：{_path}");
    }

    public void Write(string text)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        using var w = new StreamWriter(_stream, leaveOpen: true);
        w.Write(text);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _stream?.Dispose();
        File.Delete(_path);
        _disposed = true;
        Console.WriteLine("同步释放完成");
        GC.SuppressFinalize(this);
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;
        if (_stream != null) await _stream.DisposeAsync();
        File.Delete(_path);
        _disposed = true;
        Console.WriteLine("异步释放完成");
        GC.SuppressFinalize(this);
    }
}

