// 稳定的重试封装：区分“可重试”与“致命”错误
static async Task<T> RetryAsync<T>(Func<Task<T>> action, int maxAttempts = 3)
{
    int attempt = 0;
    while (true)
    {
        attempt++;
        try
        {
            return await action();
        }
        catch (Exception ex) when (IsRetryable(ex) && attempt < maxAttempts)
        {
            Console.WriteLine($"第 {attempt} 次失败（{ex.Message}），重试中…");
            await Task.Delay(attempt * 500);
        }
        // 不可重试或次数用尽：原样上抛（保留堆栈）
    }

    static bool IsRetryable(Exception ex) => ex switch
    {
        HttpRequestException { StatusCode: >= HttpStatusCode.InternalServerError } => true,
        TimeoutException => true,
        IOException => true,
        _ => false
    };
}

// 聚合异常：包一层再抛，调用方统一处理
