// 把流复制到目标（池化缓冲，避免每请求分配 8KB）
public static void CopyStream(Stream src, Stream dst)
{
    byte[] buffer = ArrayPool<byte>.Shared.Rent(8192);
    try
    {
        int read;
        while ((read = src.Read(buffer, 0, buffer.Length)) > 0)
            dst.Write(buffer, 0, read);
    }
    finally
    {
        ArrayPool<byte>.Shared.Return(buffer);
    }
}

// 统计池命中：Rent 返回的数组可能复用
var pool = ArrayPool<int>.Shared;
int[] a = pool.Rent(100);
int[] b = pool.Rent(100);
Console.WriteLine($"数组 a 容量 {a.Length}，b 容量 {b.Length}");  // 都 ≥100
pool.Return(a);
int[] c = pool.Rent(100);       // 很可能复用刚归还的 a
Console.WriteLine(ReferenceEquals(a, c));   // 可能 True（池内复用）

// 敏感数据归还前清零
byte[] secret = pool.Rent(16);
try { secret.AsSpan(0, 16).Fill(0xAB); }
finally { pool.Return(secret, clearArray: true); }
Console.WriteLine("已安全归还");

