// 自定义验证特性
[AttributeUsage(AttributeTargets.Property)]
class NotEmptyAttribute : Attribute
{
    public string Message { get; set; } = "不能为空";
}

[AttributeUsage(AttributeTargets.Property)]
class RangeAttribute : Attribute
{
    public double Min { get; }
    public double Max { get; }
    public RangeAttribute(double min, double max) { Min = min; Max = max; }
}

// 应用特性
class OrderForm
{
    [NotEmpty]
    public string? ProductName { get; set; }

    [Range(1, 999)]
    public int Qty { get; set; }

    [Range(0.01, 100000)]
    public decimal Price { get; set; }
}

// 验证引擎：反射读取特性并校验
static List<string> Validate(object obj)
{
    var errors = new List<string>();
    foreach (var prop in obj.GetType().GetProperties())
    {
        var value = prop.GetValue(obj);

        if (prop.GetCustomAttribute<NotEmptyAttribute>() is { } ne
            && (value == null || string.IsNullOrWhiteSpace(value.ToString())))
            errors.Add($"{prop.Name}: {ne.Message}");

        if (prop.GetCustomAttribute<RangeAttribute>() is { } ra && value is not null)
        {
            double d = Convert.ToDouble(value);
            if (d < ra.Min || d > ra.Max)
                errors.Add($"{prop.Name}: 必须在 {ra.Min}~{ra.Max} 之间");
        }
    }
    return errors;
}

// 演示
var bad = new OrderForm { Qty = 0, Price = 999999m };
foreach (var e in Validate(bad))
    Console.WriteLine(e);
// ProductName: 不能为空
// Qty: 必须在 1~999 之间
// Price: 必须在 0.01~100000 之间

var ok = new OrderForm { ProductName = "键盘", Qty = 2, Price = 399m };
Console.WriteLine(Validate(ok).Count);   // 0

